function getDeliveryStatus(event: typeof events[number], ops?: OperationalStore) {
  if (ops?.retried[event.eventId]) return "Retrying";
  return event.status === "ส่งแล้ว" ? "Delivered" : event.status === "รอส่ง" ? "Queued" : "Failed";
}

